def transform_consecutive_between_fill(grid):
    """Fill between consecutive least-common color cells (seed) in rows and columns."""
    n = Counter()
    for row in grid:
        for val in row:
            n[val] += 1

    if len(n) == 1:
        return [row[:] for row in grid]

    # Most common is background, least common is seed
    bg = n.most_common(1)[0][0]
    seed = min(n.keys(), key=lambda x: n[x])  # least frequent
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Row filling: between consecutive seeds
    for r in range(H):
        seed_cols = sorted([c for c in range(W) if grid[r][c] == seed])
        for i in range(len(seed_cols) - 1):
            c1, c2 = seed_cols[i], seed_cols[i+1]
            for c in range(c1 + 1, c2):
                if out[r][c] != 3:
                    out[r][c] = 3

    # Column filling: between consecutive seeds
    for c in range(W):
        seed_rows = sorted([r for r in range(H) if grid[r][c] == seed])
        for i in range(len(seed_rows) - 1):
            r1, r2 = seed_rows[i], seed_rows[i+1]
            for r in range(r1 + 1, r2):
                if out[r][c] != 3:
                    out[r][c] = 3

    return out

def count_mismatches(inp, out, expected):
    H, W = len(inp), len(inp[0])
    count = 0
    for r in range(H):
        for c in range(W):
            if out[r][c] != expected[r][c]:
                count += 1
    return count

